// Synthèse locale plus organique : harmoniques filtrées, souffle de bruit rose,
// enveloppes douces et petite réverbération. Aucun échantillon distant.
function makeNoiseBuffer(seconds=3){
 const length=Math.max(1,Math.floor(audio.sampleRate*seconds)),buffer=audio.createBuffer(1,length,audio.sampleRate),data=buffer.getChannelData(0);
 let b0=0,b1=0,b2=0;
 for(let i=0;i<length;i++){
  const white=Math.random()*2-1;
  b0=.99765*b0+white*.099046;b1=.963*b1+white*.2965164;b2=.57*b2+white*1.0526913;
  data[i]=(b0+b1+b2+white*.1848)*.08;
 }
 return buffer;
}
function makeImpulse(seconds=1.35){
 const length=Math.floor(audio.sampleRate*seconds),impulse=audio.createBuffer(2,length,audio.sampleRate);
 for(let channel=0;channel<2;channel++){
  const data=impulse.getChannelData(channel);
  for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*Math.pow(1-i/length,2.9)*.48;
 }
 return impulse;
}
