function musicTone(f,d,type,vol,end=1){tone(f,d,type,vol,end,musicBus)}
function music(dt){
 if(!prefs.sound||!prefs.music||state!=='play')return;
 const theme=musicThemes[stage%musicThemes.length];
 // Les vrais MP3 sont prioritaires ; la partition ci-dessous reste le secours
 // local si le chargement ou le décodage du morceau courant a échoué.
 if(mp3Music?.claims(theme.id))return;
 if(musicStage!==stage){musicStage=stage;note=0;musicTime=0}
 musicTime-=dt;if(musicTime>0)return;
 const boss=enemies.some(e=>e.boss),position=note%theme.melody.length,interval=theme.melody[position],beat=theme.step*(boss?.78:1);
 musicTime+=beat*(theme.swing?(note%2?1+theme.swing:1-theme.swing):1);
 const semitone=value=>theme.root*Math.pow(2,value/12);
 if(interval!==null){
  const frequency=semitone(interval)*2;
  musicTone(frequency,Math.min(1.25,beat*1.65),theme.lead,boss?.032:.024,1);
  if(theme.id==='cemetery'&&position%4===0)musicTone(frequency*2,beat*2.4,'sine',.008,1);
  if(theme.id==='marsh'&&position%4===2)musicTone(frequency*1.5,beat*1.2,'sine',.009,1);
 }
 if(note%theme.padEvery===0){
  const chord=theme.chords[Math.floor(note/theme.padEvery)%theme.chords.length],duration=Math.min(3.2,beat*theme.padEvery*1.12);
  for(const value of chord)musicTone(semitone(value),duration,'sine',boss?.012:.009,1);
 }
 if(note%theme.bassEvery===0){
  const value=theme.bass[Math.floor(note/theme.bassEvery)%theme.bass.length];
  musicTone(semitone(value)/2,Math.min(1.7,beat*theme.bassEvery*.95),'triangle',boss?.036:.026,1);
 }
 if(note%theme.pulseEvery===0)noiseBurst(boss?.18:.1,boss?.016:.006,theme.pulse,musicBus);
 if(boss&&note%4===2)noiseBurst(.12,.012,110,musicBus);
 note++;
}
function activateAudio(){if(!prefs.sound)return;initAudio();if(audio){audio.resume().then(()=>{audioSignature='';syncAudio();tone(520,.18,'sine',.06,1.25)}).catch(()=>{})}}
$('sound').onclick=()=>{prefs.sound=!prefs.sound;savePrefs();if(prefs.sound)activateAudio();else{syncAudio();if(audio)audio.suspend().catch(()=>{})}};savePrefs();
