function overlay(html){$('overlay').innerHTML=html;$('overlay').classList.remove('hidden');$('bossbar').classList.add('hidden')}
function hideOverlay(){$('overlay').classList.add('hidden')}
function dateKey(){return new Intl.DateTimeFormat('fr-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function menu(){state='menu';world=worlds[0];stage=0;const realms=[['✦','FORÊT','Murmures','#231831','#f2d09b'],['♰','CIMETIÈRE','Oubli','#112e34','#b2ddc4'],['☾','CHÂTEAU','Valse carmin','#331a32','#edacac'],['≈','MARAIS','Limons','#243521','#d8e2a3'],['✧','LANTERNES','Farandole','#351e47','#ffcc88']];overlay(`<div class="menu-shell"><div class="menu-hero"><div class="menu-art-frame"><canvas class="intro-art" id="intro" width="210" height="152"></canvas></div><div class="menu-hero-copy"><div class="eyebrow">SHOOT’EM UP · AVENTURE NOCTURNE</div><h2>La nuit<br>t’attend.</h2><p>Traverse cinq univers, améliore tes sorts et affronte les gardiens de l’aube.</p><div class="menu-actions menu-main">${checkpoint()?'<button class="secondary" id="continue"><span class="button-icon">↻</span>Reprendre</button>':''}<button class="primary" id="story"><span class="button-icon">✦</span>Commencer l’aventure</button></div></div></div><div class="world-route">${realms.map(([icon,name,sub,color,moon])=>`<div class="world-card" style="--realm:${color};--moon:${moon}"><span class="world-icon">${icon}</span><b>${name}</b><small>${sub}</small></div>`).join('')}</div><div class="menu-footer"><span class="audio-hint" id="audioHint">${prefs.sound?'<strong>♪ Musique activée</strong> · le premier clic lance l’ambiance':'♪ Active le son pour entendre la musique'}</span><div class="menu-actions"><button class="secondary" id="daily">Défi quotidien</button><button class="secondary" id="help">Comment jouer</button><button class="secondary" id="menusettings">Réglages</button></div></div><div class="menu-score">${difficultyName(prefs.difficulty)} · clavier, manette ou tactile · une partie complète : 10–15 min</div></div>`);if($('continue'))$('continue').onclick=()=>{activateAudio();resumeCheckpoint()};$('story').onclick=()=>{activateAudio();if(checkpoint()&&!confirm('Commencer une nouvelle partie remplace la sauvegarde. Continuer ?'))return;start('story')};$('daily').onclick=()=>{activateAudio();if(checkpoint()&&!confirm('Le défi remplacera la sauvegarde actuelle. Continuer ?'))return;start('daily')};$('menusettings').onclick=settings;$('help').onclick=help;const ic=$('intro').getContext('2d');ic.translate(105,78);sprite(ic,'witch',0,0,.82,0);if(window.MinuitArt?.witchFlight&&!window.MinuitArt.witchFlight.complete)window.MinuitArt.witchFlight.addEventListener('load',()=>{if(!$('intro'))return;ic.setTransform(1,0,0,1,0,0);ic.clearRect(0,0,210,152);ic.translate(105,78);sprite(ic,'witch',0,0,.82,0)},{once:true});refreshBoard()}
function highScoreKey(category=mode==='daily'?'daily':(['play','pause','choice','end'].includes(state)?runId:prefs.difficulty)){return category==='daily'?'daily:'+ (dailyDate||dateKey()):category}
function getHighScore(){const key=highScoreKey();if(!Number.isFinite(highScores[key]))highScores[key]=0;for(const r of records)if(r.category===(mode==='daily'?'daily':(['play','pause','choice','end'].includes(state)?runId:prefs.difficulty))&&(r.category!=='daily'||r.date===(dailyDate||dateKey())))highScores[key]=Math.max(highScores[key],Number(r.score)||0);return highScores[key]}
function saveHighScores(){if(window.SandboxMode)return;if(window.MinuitImporting||!recordDirty)return;try{localStorage.setItem('minuit-highscores',JSON.stringify(highScores));recordDirty=false;lastRecordSave=gameTime;window.MinuitCloud?.schedule?.()}catch{}}
function trackHighScore(){if(window.SandboxMode)return;const key=highScoreKey(),value=Math.floor(score),best=getHighScore();if(value>best){highScores[key]=value;recordDirty=true;if(!recordBroken&&value>recordAtStart){recordBroken=true;say('✦ NOUVEAU HI-SCORE ! '+value.toLocaleString('fr-FR'),3);tone(880,.22,'triangle',.1,1.5)}}$('hiValue').textContent=String(Math.max(value,highScores[key]||0)).padStart(6,'0');if($('hiValue').parentElement?.classList)$('hiValue').parentElement.classList.toggle('record-live',recordBroken);$('best').textContent=String(highScores[key]||0).padStart(6,'0');if(recordDirty&&gameTime-lastRecordSave>=1)saveHighScores()}
