function saveCheckpoint(){if(window.SandboxMode)return;if(recorded||state!=='play')return;try{localStorage.setItem('minuit-checkpoint',JSON.stringify({version:8,mode,stage,wave,seed,diff,score,lives,graze,clears,runId,dailyDate,gameTime,upgrades,player:{...player,inv:2},schedule,scareTimer,obstacleTimer,session,killCount,dailyBonus,dailyEliteKills,scrollVelocity,league:window.League?.snapshot?.(),journey:window.Journey?.snapshot?.(),sweets:drops.filter(d=>d.kind==='sweet'&&!d.taken&&d.y<950),bossLives:drops.filter(d=>d.bossLife&&d.kind==='heal'&&d.y<950),terrainDistance,routeIndex,prefsDifficulty:prefs.difficulty}));window.MinuitCloud?.schedule?.()}catch{}}
