function makeSchedule(){let list=[];const density=(diff>1?7:6)+Math.floor(stage*.75);for(let g=0;g<density;g++){const pattern=(g+wave+stage)%4;let count=3+Math.min(3,Math.floor((wave+stage)/3));for(let i=0;i<count;i++){let kind=world.foes[(g+i+wave)%world.foes.length];let x=pattern===0?100+i*600/(count-1):pattern===1?(i%2?650:150):pattern===2?400+(i-(count-1)/2)*90:80+(i*137+g*67)%640;list.push({time:1+g*2.2+i*.2,x,kind,pattern,group:g,index:i})}}return list.sort((a,b)=>a.time-b.time)}
