function spawnEnemy(d){const index=(d.group||0)*5+(d.index||0)+wave+stage,reinforced=(stage>0||wave>=3)&&index%7===0,champion=stage>=2&&wave>=4&&index%13===0,tier=champion?2:reinforced?1:0,base=1+Math.floor((wave+stage)/3)+Math.floor(stage*1.25),hp=tier===2?base*3+4:tier===1?base*2+2:base;let speed=(43+stage*13+wave*4)*diff*(tier?1.1:1);enemies.push({x:d.x,y:-35,baseX:d.x,hp,max:hp,r:tier===2?25:tier===1?22:19,speed,kind:d.kind,pattern:d.pattern,elite:tier>0,tier,age:0,fire:Math.max(.8,2-stage*.22)+rng()*1.5,poison:0,poisonTick:0,id:rng(),hit:0})}
