function dailyWaveReward(){window.League?.event?.('waves',1);if(clean)window.League?.event?.('cleanWaves',1);if(mode!=='daily')return;dailyAward(150*(stage+1)*wave+(clean?100*(stage+1):0),'Vague '+wave+(clean?' sans dégâts':''))}
function updateDailyInfo(){if(!$('dailyinfo'))return;$('dailyinfo').textContent=mode==='daily'?'Défi du '+(dailyDate||dateKey())+' · BONUS +'+dailyBonus+' points. Vagues : 150 × univers × vague, +100 × univers sans dégâts. Gardiens : 750 × univers. Élites : 100 × univers. 8 frôlements : +150.':'Défi du '+dateKey()+' : gagne des points supplémentaires en terminant les vagues, en vainquant les élites et en frôlant leurs tirs. Même graine et difficulté pour tous.'}
const upgradeDefs=[['rocket','explosions','Roquettes spectrales','Missiles guidés pendant 10 secondes. Une roquette, puis deux dès le 3e univers.',2],['fragment','explosions','Fragmentation','Les roquettes libèrent des éclats après leur explosion.',2],['chain','explosions','Réaction en chaîne','Une explosion peut déclencher une seconde déflagration.',2],['flame','explosions','Flamme maudite','Les roquettes embrasent les toiles et les ennemis proches.',2],['poison','malédictions','Venin de minuit','Les tirs empoisonnent ; les dégâts persistent.',3],['spread','malédictions','Contagion','Les ennemis vaincus transmettent leur poison.',2],['fire','malédictions','Grimoire de puissance','Cadence accrue, puis dégâts et double tir.',3],['familiar','spectres','Familier lunaire','Un, puis deux compagnons tirent à tes côtés.',2],['pierce','spectres','Aiguilles fantômes','Les sorts traversent un ennemi supplémentaire.',2],['laser','spectres','Rayon spectral','Un rayon périodique traverse toute la colonne de tir.',3]];
function upgradeCap(key){if(key==='rocket')return stage>=2?2:1;if(key==='fire')return stage===0?1:stage===1?2:3;if(['poison','pierce'].includes(key))return stage===0?1:stage===1?2:3;if(['familiar','laser'].includes(key))return stage<3?1:2;return stage<3?1:2}
