function updateHUD(){trackHighScore();$('score').textContent=String(Math.floor(score)).padStart(6,'0');$('combo').textContent='COMBO ×'+combo;$('dailyBonusHUD').textContent=mode==='daily'?'BONUS DÉFI +'+dailyBonus:'';$('wave').textContent=String(wave).padStart(2,'0')+' / 05';$('realmHUD').textContent=world.short;$('lives').textContent='♥ '.repeat(Math.max(0,lives));$('graze').textContent=player.missileTime>0?'MISSILES '+Math.ceil(player.missileTime)+'s':graze+' FRÔLEMENTS';if(Math.ceil(player.missileTime||0)!==player.lastMissileUI){player.lastMissileUI=Math.ceil(player.missileTime||0);updateLoadout()}$('dash').textContent=player.dashCD>0?'✦ '+player.dashCD.toFixed(1)+'s':'✦ Esquive';const boss=enemies.find(e=>e.boss);$('bossbar').classList.add('hidden');if(boss){$('bossname').textContent=world.boss;$('bosshp').style.width=Math.max(0,boss.hp/boss.max*100)+'%';$('bossphase').textContent='PHASE '+boss.phase+' / 3'+(boss.kind==='demon'&&enemies.some(e=>e.lantern)?' · DÉTRUIS LES LANTERNES':'')}$('status').textContent=world.name+' · '+Math.floor(gameTime/60)+' min '+String(Math.floor(gameTime%60)).padStart(2,'0')+' s · VOL '+Math.round(scrollSpeed()/58*100)+' %'}
function broomMuzzle(){let a=player.lean||0;return{x:Math.max(8,Math.min(W-8,player.x+Math.sin(a)*67)),y:player.y-Math.cos(a)*67}}
function held(k){return !!moveInput[k.toLowerCase()]}
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key))e.preventDefault();moveInput[e.key.toLowerCase()]=true;pointer=null;if(e.repeat)return;if(e.key.toLowerCase()===prefs.keys.pause.toLowerCase()||e.key==='Escape')togglePause();if(e.key.toLowerCase()===prefs.keys.dash.toLowerCase())dodge();if(state==='menu'&&e.key==='Enter')start('story')});window.addEventListener('keyup',e=>delete moveInput[e.key.toLowerCase()]);window.addEventListener('blur',()=>{moveInput={};pointer=null;if(state==='play')pauseScreen()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='play')pauseScreen()});
function coords(e){let r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height}}
let drag=null;
function hideTouchStick(){const el=$('touchStick');if(el){el.classList.add('hidden');if(el.firstElementChild)el.firstElementChild.style.transform='translate(0,0)'}}
function showTouchStick(){const el=$('touchStick');if(!el||!drag?.touch)return;const r=c.getBoundingClientRect();el.style.left=(drag.cx-r.left)+'px';el.style.top=(drag.cy-r.top)+'px';el.classList.remove('hidden')}
function moveTouchStick(e){const el=$('touchStick');if(!el||!drag?.touch||!el.firstElementChild)return;const dx=Math.max(-26,Math.min(26,e.clientX-drag.cx)),dy=Math.max(-26,Math.min(26,e.clientY-drag.cy));el.firstElementChild.style.transform=`translate(${dx}px,${dy}px)`}
c.addEventListener('pointerdown',e=>{
 if(state!=='play'||drag?.touch)return;
 e.preventDefault();try{c.setPointerCapture(e.pointerId)}catch{}
 const p=coords(e);drag={...p,px:player.x,py:player.y,touch:e.pointerType!=='mouse',id:e.pointerId,cx:e.clientX,cy:e.clientY};
 if(!drag.touch)pointer=p;else showTouchStick();
});
c.addEventListener('pointermove',e=>{
 if(state!=='play')return;
 const p=coords(e);
 if(e.pointerType==='mouse')pointer=p;
 else if(drag?.touch&&drag.id===e.pointerId){
  // Un glisser relatif, légèrement amplifié sur petit écran : pas de saut au
  // toucher et l’autre main reste libre pour le sort ou l’esquive.
  const sensitivity=1.15;pointer={x:drag.px+(p.x-drag.x)*sensitivity,y:drag.py+(p.y-drag.y)*sensitivity};moveTouchStick(e);
 }
});
function release(e){if(e&&drag?.touch&&e.pointerId!==drag.id)return;drag=null;pointer=null;hideTouchStick()}
c.addEventListener('pointerup',release);c.addEventListener('pointercancel',release);c.addEventListener('contextmenu',e=>e.preventDefault());
function menuPad(){const gp=navigator.getGamepads?.()[0];if(!gp)return;const press=gp.buttons[0]?.pressed;if(state==='pause'&&press&&!padDash){state='play';hideOverlay()}else if(['menu','league-menu'].includes(state)&&press&&!padDash)start('story');padDash=press;if(gp.buttons[9]?.pressed&&!padPause&&state==='pause'){state='play';hideOverlay()}padPause=gp.buttons[9]?.pressed}
function safeText(s){return String(s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function refreshBoard(){const filter=mode==='daily'?'daily':(['play','pause','choice','end'].includes(state)?runId:prefs.difficulty);const matches=r=>r.category===filter&&(filter!=='daily'||r.date===dailyDate);let list=boardTab==='local'?records.filter(matches).slice(0,10):serverScores;$('best').textContent=String(getHighScore()).padStart(6,'0');$('leaderboard').innerHTML=list.length?list.slice(0,10).map((r,i)=>`<div class="rankrow"><span>${i+1}. ${safeText(r.name||'Sorcière')}</span><b>${String(r.score).padStart(6,'0')}</b></div>`).join(''):'<div class="tiny">La prochaine légende, c’est peut-être toi.</div>';$('netstatus').textContent=(boardTab==='local'?'Sauvegarde locale · ':serverMessage+' · ')+(filter==='daily'?'Défi '+dailyDate:difficultyName(filter));updateDailyInfo()}
async function fetchScores(){serverMessage='Connexion…';refreshBoard();try{let q=new URLSearchParams({category:mode==='daily'?'daily':(['play','pause','choice','end'].includes(state)?runId:prefs.difficulty),date:dailyDate||dateKey()});const r=await fetch('/api/scores?'+q);if(!r.ok)throw Error();let d=await r.json();serverScores=d.scores;serverMessage='Classement partagé · non homologué'}catch{serverScores=[];serverMessage='Serveur indisponible · records locaux conservés'}refreshBoard()}
$('localtab').onclick=()=>{boardTab='local';refreshBoard()};$('onlinetab').onclick=()=>{boardTab='server';fetchScores()};
function teamEndRows(data){const rows=(data?.scores||[]).slice(0,10);return rows.length?rows.map(r=>`<div class="team-end-row ${r.isYou?'team-you':''}"><b>#${Number(r.rank)||0}</b><span>${safeText(r.displayName||'Sorcière')}${r.isYou?'<small>TOI</small>':''}</span><strong>${Number(r.score||0).toLocaleString('fr-FR')}</strong></div>`).join(''):'<div class="tiny">Aucun score de team pour le moment.</div>'}
function renderTeamEnd(data){const slot=$('teamEndPanel');if(!slot)return;if(data?.skipped||!data?.team){slot.remove();return}const mine=(data.scores||[]).find(r=>r.isYou),rank=mine?.rank||'—';slot.innerHTML=`<div class="team-end-heading"><span>🏆 TEAM · ${safeText(data.team.name||'Sans nom')}</span><b>TA POSITION : #${rank}</b></div><div class="team-end-board">${teamEndRows(data)}</div><div class="tiny">Classement du meilleur score de chaque membre · ${Number(data.team.memberCount)||0} membre${Number(data.team.memberCount)>1?'s':''}</div>`;const status=$('teamResultStatus'),result=data.result||{},remaining=result.gamesRemaining??data.team.gamesRemaining;if(status)status.textContent=(result.duplicate?'Vol déjà comptabilisé dans la team.':result.improved?'Nouveau highscore de team !':'Score du vol transmis à la team.')+(remaining===null||remaining===undefined?'':' · '+Number(remaining)+' partie'+(Number(remaining)>1?'s':'')+' restante'+(Number(remaining)>1?'s':''));slot.classList.remove('team-end-reveal');requestAnimationFrame(()=>slot.classList.add('team-end-reveal'));if(prefs.sound){tone(392,.16,'sine',.045,1.22);setTimeout(()=>tone(587,.24,'sine',.035,1.08),110)}}
function loadTeamEndScore(value){const slot=$('teamEndPanel');if(!slot||!window.MinuitCloud?.finishTeamScore)return;slot.innerHTML='<div class="tiny">Synchronisation du score avec la team…</div>';window.MinuitCloud.finishTeamScore(value).then(renderTeamEnd).catch(()=>{if(slot)slot.innerHTML='<div class="tiny">Score enregistré localement ; classement team momentanément indisponible.</div>'})}
function end(win){release();if(recorded)return;trackHighScore();saveHighScores();recorded=true;try{localStorage.removeItem('minuit-checkpoint')}catch{}state='end';const result={name:prefs.name,score:Math.floor(score),category:runId,date:dailyDate,stage:stage+1,clears,win,time:Math.floor(gameTime)};window.MinuitLastScore=result;records.push(result);records.sort((a,b)=>b.score-a.score);records=records.slice(0,150);try{localStorage.setItem('minuit-v2-scores',JSON.stringify(records))}catch{}const teamSlot=window.MinuitCloud?.connected&&!window.Journey?.finish?'<section class="team-end-panel" id="teamEndPanel"><div class="tiny">Préparation du classement team…</div></section>':'';overlay(`<div class="eyebrow">${win?'LES CINQ GARDIENS SONT TOMBÉS':'LA NUIT GARDE ENCORE SES SECRETS'}</div><h2>${win?'Enfin, l’aube.':'Vous êtes mort !'}</h2><p>${win?'Tu as traversé les cinq univers. La sorcière peut rentrer.':'Dernier coup reçu : '+lastDamage+'. Chaque nuit t’apprend un nouveau chemin.'}</p>${recordBroken?'<div class="new-record">✦ NOUVEAU HI-SCORE ✦</div>':''}<div class="statsline"><span>Score <b>${Math.floor(score)}</b></span><span>Record <b>${getHighScore()}</b></span><span>Frôlements <b>${graze}</b></span><span>Gardiens <b>${clears}/5</b></span>${mode==='daily'?'<span>Bonus défi <b>+'+dailyBonus+'</b></span>':''}</div>${teamSlot}<div class="tiny" id="submitstatus">Record enregistré sur cet appareil.</div><br><div class="menu-actions"><button class="primary" id="retry">Une autre nuit →</button><button class="secondary" id="return">Menu</button></div>`);$('retry').onclick=()=>start(mode);$('return').onclick=menu;if(teamSlot)loadTeamEndScore({score:Math.floor(score),mode:mode==='daily'?'daily':(window.League?.active?'ranked':'free'),difficulty:prefs.difficulty,stage:stage+1,wave,id:session||runId});refreshBoard()}

